"""Predefined backtesting strategies."""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any


@dataclass
class StrategySignal:
    """Signal generated by a strategy."""

    action: str  # "buy", "sell", "hold"
    confidence: float = 0.0  # 0.0 to 1.0
    reason: str = ""
    metadata: dict[str, Any] = field(default_factory=dict)


class BaseStrategy(ABC):
    """Base class for backtesting strategies."""

    name: str = "base"
    description: str = ""

    @abstractmethod
    def generate_signals(self, data: list[dict[str, Any]]) -> list[StrategySignal]:
        """Generate buy/sell signals from OHLCV data.

        Args:
            data: List of dicts with keys: date, open, high, low, close, volume.
                  Sorted chronologically (oldest first).

        Returns:
            List of StrategySignal, one per data point.
        """
        ...

    @staticmethod
    def _sma(prices: list[float], period: int) -> list[float | None]:
        """Calculate Simple Moving Average."""
        result: list[float | None] = [None] * len(prices)
        for i in range(period - 1, len(prices)):
            result[i] = sum(prices[i - period + 1 : i + 1]) / period
        return result

    @staticmethod
    def _ema(prices: list[float], period: int) -> list[float | None]:
        """Calculate Exponential Moving Average."""
        result: list[float | None] = [None] * len(prices)
        if len(prices) < period:
            return result
        # Seed with SMA
        result[period - 1] = sum(prices[:period]) / period
        multiplier = 2 / (period + 1)
        for i in range(period, len(prices)):
            result[i] = (prices[i] - result[i - 1]) * multiplier + result[i - 1]  # type: ignore
        return result

    @staticmethod
    def _rsi(prices: list[float], period: int = 14) -> list[float | None]:
        """Calculate Relative Strength Index."""
        result: list[float | None] = [None] * len(prices)
        if len(prices) < period + 1:
            return result

        gains = []
        losses = []
        for i in range(1, len(prices)):
            change = prices[i] - prices[i - 1]
            gains.append(max(change, 0))
            losses.append(max(-change, 0))

        # Initial average
        avg_gain = sum(gains[:period]) / period
        avg_loss = sum(losses[:period]) / period

        if avg_loss == 0:
            result[period] = 100.0
        else:
            rs = avg_gain / avg_loss
            result[period] = 100 - (100 / (1 + rs))

        for i in range(period, len(gains)):
            avg_gain = (avg_gain * (period - 1) + gains[i]) / period
            avg_loss = (avg_loss * (period - 1) + losses[i]) / period
            if avg_loss == 0:
                result[i + 1] = 100.0
            else:
                rs = avg_gain / avg_loss
                result[i + 1] = 100 - (100 / (1 + rs))

        return result

    @staticmethod
    def _bollinger_bands(
        prices: list[float], period: int = 20, std_dev: float = 2.0
    ) -> tuple[list[float | None], list[float | None], list[float | None]]:
        """Calculate Bollinger Bands (upper, middle, lower)."""
        middle = BaseStrategy._sma(prices, period)
        upper: list[float | None] = [None] * len(prices)
        lower: list[float | None] = [None] * len(prices)

        for i in range(period - 1, len(prices)):
            window = prices[i - period + 1 : i + 1]
            mean = sum(window) / len(window)
            variance = sum((x - mean) ** 2 for x in window) / len(window)
            std = variance ** 0.5
            upper[i] = mean + std_dev * std
            lower[i] = mean - std_dev * std

        return upper, middle, lower

    @staticmethod
    def _atr(
        highs: list[float], lows: list[float], closes: list[float], period: int = 14
    ) -> list[float | None]:
        """Calculate Average True Range."""
        result: list[float | None] = [None] * len(closes)
        if len(closes) < 2:
            return result

        true_ranges = [highs[0] - lows[0]]
        for i in range(1, len(closes)):
            tr = max(
                highs[i] - lows[i],
                abs(highs[i] - closes[i - 1]),
                abs(lows[i] - closes[i - 1]),
            )
            true_ranges.append(tr)

        if len(true_ranges) < period:
            return result

        result[period - 1] = sum(true_ranges[:period]) / period
        for i in range(period, len(true_ranges)):
            result[i] = (result[i - 1] * (period - 1) + true_ranges[i]) / period  # type: ignore

        return result


class MomentumStrategy(BaseStrategy):
    """Momentum strategy: buy when fast MA crosses above slow MA, sell on cross below.

    Uses dual moving average crossover with RSI filter.
    """

    name = "momentum"
    description = "Dual MA crossover with RSI filter"

    def __init__(self, fast_period: int = 20, slow_period: int = 50, rsi_period: int = 14):
        self.fast_period = fast_period
        self.slow_period = slow_period
        self.rsi_period = rsi_period

    def generate_signals(self, data: list[dict[str, Any]]) -> list[StrategySignal]:
        n = len(data)
        if n < self.slow_period + 1:
            return [StrategySignal(action="hold") for _ in data]

        closes = [d["close"] for d in data]
        fast_ma = self._sma(closes, self.fast_period)
        slow_ma = self._sma(closes, self.slow_period)
        rsi = self._rsi(closes, self.rsi_period)

        signals: list[StrategySignal] = []
        prev_above = None

        for i in range(n):
            if fast_ma[i] is None or slow_ma[i] is None:
                signals.append(StrategySignal(action="hold"))
                continue

            above = fast_ma[i] > slow_ma[i]  # type: ignore
            current_rsi = rsi[i]

            if prev_above is not None and above != prev_above:
                if above and current_rsi is not None and current_rsi < 70:
                    signals.append(StrategySignal(
                        action="buy",
                        confidence=min((current_rsi or 50) / 70, 1.0),
                        reason=f"MA{self.fast_period} crossed above MA{self.slow_period}, RSI={current_rsi:.1f}",
                        metadata={"fast_ma": fast_ma[i], "slow_ma": slow_ma[i], "rsi": current_rsi},
                    ))
                elif not above and current_rsi is not None and current_rsi > 30:
                    signals.append(StrategySignal(
                        action="sell",
                        confidence=min((100 - (current_rsi or 50)) / 70, 1.0),
                        reason=f"MA{self.fast_period} crossed below MA{self.slow_period}, RSI={current_rsi:.1f}",
                        metadata={"fast_ma": fast_ma[i], "slow_ma": slow_ma[i], "rsi": current_rsi},
                    ))
                else:
                    signals.append(StrategySignal(action="hold"))
            else:
                signals.append(StrategySignal(action="hold"))

            prev_above = above

        return signals


class MeanReversionStrategy(BaseStrategy):
    """Mean reversion: buy when price touches lower Bollinger Band, sell at upper."""

    name = "mean_reversion"
    description = "Bollinger Band bounce strategy"

    def __init__(self, bb_period: int = 20, bb_std: float = 2.0, rsi_period: int = 14):
        self.bb_period = bb_period
        self.bb_std = bb_std
        self.rsi_period = rsi_period

    def generate_signals(self, data: list[dict[str, Any]]) -> list[StrategySignal]:
        n = len(data)
        if n < self.bb_period + 1:
            return [StrategySignal(action="hold") for _ in data]

        closes = [d["close"] for d in data]
        upper, middle, lower = self._bollinger_bands(closes, self.bb_period, self.bb_std)
        rsi = self._rsi(closes, self.rsi_period)

        signals: list[StrategySignal] = []
        in_position = False

        for i in range(n):
            if lower[i] is None or upper[i] is None:
                signals.append(StrategySignal(action="hold"))
                continue

            close = closes[i]
            current_rsi = rsi[i]

            if not in_position and close <= lower[i]:  # type: ignore
                if current_rsi is not None and current_rsi < 35:
                    signals.append(StrategySignal(
                        action="buy",
                        confidence=min((35 - current_rsi) / 35, 1.0),
                        reason=f"Price touched lower BB, RSI oversold={current_rsi:.1f}",
                        metadata={"upper_bb": upper[i], "lower_bb": lower[i], "rsi": current_rsi},
                    ))
                    in_position = True
                else:
                    signals.append(StrategySignal(action="hold"))
            elif in_position and close >= upper[i]:  # type: ignore
                signals.append(StrategySignal(
                    action="sell",
                    confidence=min(current_rsi / 100 if current_rsi else 0.5, 1.0),
                    reason=f"Price touched upper BB, RSI={current_rsi:.1f}",
                    metadata={"upper_bb": upper[i], "lower_bb": lower[i], "rsi": current_rsi},
                ))
                in_position = False
            else:
                signals.append(StrategySignal(action="hold"))

        return signals


class TrendFollowingStrategy(BaseStrategy):
    """Trend following: buy when price > SMA and ATR confirms trend, sell on stop-loss."""

    name = "trend_following"
    description = "ATR-based trend following with trailing stop"

    def __init__(
        self,
        sma_period: int = 50,
        atr_period: int = 14,
        atr_multiplier: float = 2.0,
        rsi_period: int = 14,
    ):
        self.sma_period = sma_period
        self.atr_period = atr_period
        self.atr_multiplier = atr_multiplier
        self.rsi_period = rsi_period

    def generate_signals(self, data: list[dict[str, Any]]) -> list[StrategySignal]:
        n = len(data)
        if n < max(self.sma_period, self.atr_period) + 1:
            return [StrategySignal(action="hold") for _ in data]

        closes = [d["close"] for d in data]
        highs = [d["high"] for d in data]
        lows = [d["low"] for d in data]

        sma = self._sma(closes, self.sma_period)
        atr = self._atr(highs, lows, closes, self.atr_period)
        rsi = self._rsi(closes, self.rsi_period)

        signals: list[StrategySignal] = []
        in_position = False
        entry_price = 0.0
        trailing_stop = 0.0

        for i in range(n):
            if sma[i] is None or atr[i] is None:
                signals.append(StrategySignal(action="hold"))
                continue

            close = closes[i]
            current_rsi = rsi[i]

            if not in_position:
                # Buy when price above SMA, RSI not overbought, and ATR confirms volatility
                if (
                    close > sma[i]  # type: ignore
                    and current_rsi is not None
                    and 30 < current_rsi < 70
                ):
                    signals.append(StrategySignal(
                        action="buy",
                        confidence=0.7,
                        reason=f"Price above SMA{self.sma_period}, RSI={current_rsi:.1f}, ATR={atr[i]:.2f}",
                        metadata={"sma": sma[i], "atr": atr[i], "rsi": current_rsi},
                    ))
                    in_position = True
                    entry_price = close
                    trailing_stop = close - self.atr_multiplier * atr[i]  # type: ignore
                else:
                    signals.append(StrategySignal(action="hold"))
            else:
                # Update trailing stop
                new_stop = close - self.atr_multiplier * atr[i]  # type: ignore
                trailing_stop = max(trailing_stop, new_stop)

                if close <= trailing_stop or (current_rsi is not None and current_rsi > 80):
                    signals.append(StrategySignal(
                        action="sell",
                        confidence=0.8,
                        reason=f"Trailing stop hit ({trailing_stop:.2f}) or RSI overbought" if close <= trailing_stop else f"RSI overbought={current_rsi:.1f}",
                        metadata={"trailing_stop": trailing_stop, "entry_price": entry_price, "rsi": current_rsi},
                    ))
                    in_position = False
                else:
                    signals.append(StrategySignal(action="hold"))

        return signals


class OpeningRangeBreakoutStrategy(BaseStrategy):
    """Opening Range Breakout (ORB): buy on breakout of first 15-30 min range.

    Popular in India for Nifty/Bank Nifty intraday. The algorithm captures the
    first 15 minutes' high/low and trades the breakout direction.
    """

    name = "orb"
    description = "Opening Range Breakout — first 15-min range breakout"

    def __init__(self, range_minutes: int = 15, atr_period: int = 14, atr_multiplier: float = 1.5):
        self.range_minutes = range_minutes
        self.atr_period = atr_period
        self.atr_multiplier = atr_multiplier

    def generate_signals(self, data: list[dict[str, Any]]) -> list[StrategySignal]:
        n = len(data)
        if n < self.atr_period + 2:
            return [StrategySignal(action="hold") for _ in data]

        closes = [d["close"] for d in data]
        highs = [d["high"] for d in data]
        lows = [d["low"] for d in data]

        atr = self._atr(highs, lows, closes, self.atr_period)

        signals: list[StrategySignal] = []
        in_position = False
        range_high = 0.0
        range_low = 0.0
        entry_price = 0.0
        stop_loss = 0.0

        # Use first data points to establish opening range (simplified: first 15 bars if daily)
        opening_range_bars = min(self.range_minutes, n // 4) if n > 20 else 3
        or_high = max(highs[:opening_range_bars])
        or_low = min(lows[:opening_range_bars])
        range_established = False

        for i in range(n):
            if atr[i] is None:
                signals.append(StrategySignal(action="hold"))
                continue

            close = closes[i]
            high = highs[i]
            low = lows[i]

            # Establish opening range from first few bars
            if not range_established and i >= opening_range_bars:
                range_high = or_high
                range_low = or_low
                range_established = True

            if not range_established:
                signals.append(StrategySignal(action="hold"))
                continue

            if not in_position:
                # Buy on breakout above range high
                if high > range_high:
                    signals.append(StrategySignal(
                        action="buy",
                        confidence=0.75,
                        reason=f"Breakout above OR high={range_high:.2f}, ATR={atr[i]:.2f}",
                        metadata={"range_high": range_high, "range_low": range_low, "atr": atr[i]},
                    ))
                    in_position = True
                    entry_price = close
                    stop_loss = range_low - self.atr_multiplier * atr[i]  # type: ignore
                else:
                    signals.append(StrategySignal(action="hold"))
            else:
                # Update stop loss
                new_stop = close - self.atr_multiplier * atr[i]  # type: ignore
                stop_loss = max(stop_loss, new_stop)

                if close <= stop_loss:
                    signals.append(StrategySignal(
                        action="sell",
                        confidence=0.8,
                        reason=f"Stop loss hit at {stop_loss:.2f}",
                        metadata={"entry_price": entry_price, "stop_loss": stop_loss, "atr": atr[i]},
                    ))
                    in_position = False
                else:
                    signals.append(StrategySignal(action="hold"))

        return signals


class BreakoutStrategy(BaseStrategy):
    """Breakout strategy: buy when price breaks above resistance with volume confirmation.

    Uses ATR-based support/resistance levels and volume filter.
    """

    name = "breakout"
    description = "ATR-based breakout with volume confirmation"

    def __init__(
        self,
        lookback_period: int = 20,
        atr_period: int = 14,
        atr_multiplier: float = 1.5,
        volume_multiplier: float = 1.5,
    ):
        self.lookback_period = lookback_period
        self.atr_period = atr_period
        self.atr_multiplier = atr_multiplier
        self.volume_multiplier = volume_multiplier

    def generate_signals(self, data: list[dict[str, Any]]) -> list[StrategySignal]:
        n = len(data)
        if n < max(self.lookback_period, self.atr_period) + 1:
            return [StrategySignal(action="hold") for _ in data]

        closes = [d["close"] for d in data]
        highs = [d["high"] for d in data]
        lows = [d["low"] for d in data]
        volumes = [d.get("volume", 0) for d in data]

        atr = self._atr(highs, lows, closes, self.atr_period)

        signals: list[StrategySignal] = []
        in_position = False
        entry_price = 0.0
        trailing_stop = 0.0

        # Pad beginning with hold signals so length matches data
        for _ in range(self.lookback_period):
            signals.append(StrategySignal(action="hold"))

        for i in range(self.lookback_period, n):
            if atr[i] is None:
                signals.append(StrategySignal(action="hold"))
                continue

            close = closes[i]
            high = highs[i]

            # Calculate resistance from lookback period
            resistance = max(highs[i - self.lookback_period : i])

            # Calculate average volume for comparison
            avg_volume = sum(volumes[i - self.lookback_period : i]) / self.lookback_period if self.lookback_period > 0 else 0
            current_volume = volumes[i]

            if not in_position:
                # Buy on breakout above resistance with volume confirmation
                if (
                    high > resistance
                    and current_volume > avg_volume * self.volume_multiplier  # type: ignore
                ):
                    signals.append(StrategySignal(
                        action="buy",
                        confidence=0.7,
                        reason=f"Breakout above resistance={resistance:.2f}, volume={current_volume}/{avg_volume:.0f}",
                        metadata={"resistance": resistance, "atr": atr[i], "volume_ratio": current_volume / avg_volume if avg_volume > 0 else 0},
                    ))
                    in_position = True
                    entry_price = close
                    trailing_stop = close - self.atr_multiplier * atr[i]  # type: ignore
                else:
                    signals.append(StrategySignal(action="hold"))
            else:
                # Update trailing stop
                new_stop = close - self.atr_multiplier * atr[i]  # type: ignore
                trailing_stop = max(trailing_stop, new_stop)

                if close <= trailing_stop:
                    signals.append(StrategySignal(
                        action="sell",
                        confidence=0.8,
                        reason=f"Trailing stop hit at {trailing_stop:.2f}",
                        metadata={"entry_price": entry_price, "trailing_stop": trailing_stop, "atr": atr[i]},
                    ))
                    in_position = False
                else:
                    signals.append(StrategySignal(action="hold"))

        return signals


STRATEGY_MAP: dict[str, type[BaseStrategy]] = {
    "momentum": MomentumStrategy,
    "mean_reversion": MeanReversionStrategy,
    "trend_following": TrendFollowingStrategy,
    "orb": OpeningRangeBreakoutStrategy,
    "breakout": BreakoutStrategy,
}


def get_strategy(name: str, **kwargs: Any) -> BaseStrategy:
    """Get a strategy by name.

    Args:
        name: Strategy name (momentum, mean_reversion, trend_following, orb, breakout).
        **kwargs: Additional parameters for the strategy.

    Returns:
        Strategy instance.

    Raises:
        ValueError: If strategy name is unknown.
    """
    if name not in STRATEGY_MAP:
        available = ", ".join(STRATEGY_MAP.keys())
        raise ValueError(f"Unknown strategy '{name}'. Available: {available}")
    return STRATEGY_MAP[name](**kwargs)
